(function(){'use strict';const $=id=>document.getElementById(id),status=$('account-status');let factorId='',busy=false;
async function api(action,data){const r=await fetch('/api/account/'+action,{credentials:'same-origin',...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{}),signal:AbortSignal.timeout(20000)});let result;try{result=await r.json()}catch{throw Error('Account access is temporarily unavailable. Please try again later.')}if(!r.ok)throw Error(result.error||'This action could not be completed.');return result}
async function load(){const r=await api('session');$('account-login').hidden=r.signedIn;$('account-profile').hidden=!r.signedIn;$('account-security').hidden=!r.signedIn;$('account-admin').hidden=!r.operator;if(!r.signedIn){status.textContent='Sign in using the account supplied for your plan.';return}status.textContent='Signed in. Only account and plan information is stored.';$('account-identity').textContent=r.email;$('account-id').textContent=r.accountId;$('account-plans').textContent=r.access.length?r.access.map(x=>x.plan+' · valid until '+new Date(x.ends_at).toLocaleDateString('en-IN')).join('; '):'No active verified plan is currently available. Complete authenticator verification and check plan assignment with your provider.';$('account-open').hidden=!r.access.some(x=>x.guided);factorId=r.factors[0]?.id||'';$('account-enrol').hidden=!!factorId;$('account-mfa').hidden=false;}
async function run(action){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await action()}catch(e){status.textContent=e.message;status.focus()}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false)}}
$('account-form').onsubmit=e=>{e.preventDefault();run(async()=>{const form=e.target;await api('login',{email:form.elements.email.value,password:form.elements.password.value});form.elements.password.value='';await load()})};
$('account-refresh').onclick=()=>run(load);$('account-logout').onclick=()=>run(async()=>{try{await api('logout',{})}finally{$('account-secret').textContent='';$('account-secret-wrap').hidden=true;factorId='';await load()}});
$('account-enrol').onclick=()=>run(async()=>{const r=await api('mfa/enrol',{});factorId=r.factorId;$('account-secret').textContent=r.secret;$('account-secret-wrap').hidden=false;status.textContent='Add the setup key in your authenticator app, then enter its code.'});
$('account-mfa').onsubmit=e=>{e.preventDefault();run(async()=>{if(!factorId)throw Error('Set up an authenticator first.');await api('mfa/verify',{factorId,code:e.target.elements.code.value});e.target.reset();$('account-secret').textContent='';$('account-secret-wrap').hidden=true;await load();status.textContent='Authenticator verified. Your active plan, if assigned, is shown above.'})};
async function adminList(){const id=$('admin-grant').elements.accountId.value;if(!id)return;const r=await api('admin/access',{accountId:id}),list=$('admin-access-list');list.replaceChildren();for(const item of r.result){const row=document.createElement('p'),text=document.createElement('span');text.textContent=item.plan+' · '+item.status+' · ends '+item.ends_at+' ';row.append(text);if(item.status==='active'){const button=document.createElement('button');button.type='button';button.className='btn btn-light';button.textContent='Revoke this access';button.onclick=()=>{if(!confirm('Revoke this customer’s '+item.plan+' access?'))return;run(async()=>{await api('admin/revoke',{accessId:item.access_id});await adminList();$('admin-result').textContent='Access revoked. Already downloaded documents remain on the customer’s device.'})};row.append(button)}list.append(row)}}
$('admin-lookup').onsubmit=e=>{e.preventDefault();run(async()=>{$('admin-grant').elements.accountId.value='';$('admin-access-list').replaceChildren();const r=await api('admin/lookup',{email:e.target.elements.email.value});if(!r.result.length)throw Error('No confirmed account found. Provision and confirm the customer account first.');const f=$('admin-grant').elements;f.accountId.value=r.result[0].account_id;f.verificationReference.value=crypto.randomUUID();f.startsAt.value=new Date().toISOString().slice(0,10);f.verified.checked=false;await adminList();$('admin-result').textContent='Confirmed account found. Verify purchase before assigning access.'})};
$('admin-grant').onsubmit=e=>{e.preventDefault();run(async()=>{const f=e.target.elements;if(!f.verified.checked)throw Error('Verify the purchase first.');await api('admin/grant',{accountId:f.accountId.value,plan:f.plan.value,startsAt:f.startsAt.value+'T00:00:00+05:30',endsAt:f.endsAt.value+'T00:00:00+05:30',verificationReference:f.verificationReference.value});f.verified.checked=false;f.verificationReference.value=crypto.randomUUID();await adminList();$('admin-result').textContent='Access assigned. Ask the customer to verify their authenticator and refresh access.'})};
 status.tabIndex=-1;api('config').then(async c=>{if(!c.enabled||!c.configured){$('account-login').hidden=true;status.textContent='Account access is being configured. Public guidance and the procedural preview remain available.';return}document.querySelector('#account-form button').disabled=false;await load()}).catch(e=>{status.textContent=e.message});})();
